#!/usr/bin/env bash
# 「拆」页整体风格 mockup（GPT Image，在真实页面截图上改）：四个方向，每个方向先出整页，再以整页为底出三帧动效分镜
#   bash docs/mockups/split2/gen.sh pages     # 第一轮：四张整页
#   bash docs/mockups/split2/gen.sh boards    # 第二轮：四组分镜（需要第一轮的整页）
set -u
cd "$(dirname "$0")"
G=~/.claude/skills/multimodal-extension/scripts/gpt_image.py
BASE=base-split-both.png

KEEP='Edit this real website screenshot: the "拆 · 只吃馅怎么算" page of a Chinese fitness meal-planning website (it shows how a double cheeseburger splits into ingredients, which ones you eat now, keep for tomorrow, or remove when ordering). Redesign the visual style and the layout of the page body according to the direction below, but keep ALL the content. Keep the top navigation bar exactly as in the screenshot. Use these Chinese texts exactly as written, and NO other text: "回到首页", "SPLIT SETS", "拆 · 只吃馅怎么算", "官方只公布整份营养。我们把它拆到每一种配料，于是「只吃馅」吃进去多少、面包留下多少，都能算出来。", "吃法", "整份吃", "下单去吉士", "到手只吃馅", "去吉士 + 只吃馅" (this one is the selected option), "这一顿", "182", "大卡", "蛋白质 16 g · 碳水 2 g", ingredient labels "顶面包", "酸黄瓜等", "吉士", "牛肉饼", "底面包" with calories "两片共 142 大卡", "15 大卡", "45 大卡", "91 大卡", group labels "吃掉 182 大卡", "留到明早 157 大卡", "下单去掉 90 大卡", "省钱对比", "同一家店，同样 400 大卡以内、蛋白质 30 克以上", "只能整份吃", "¥32.0", "2 × 薄皮焦香V翅", "允许拆着吃", "¥27.8", "2 份人气经典随心配，高达吉士双牛堡去干酪、只吃馅", "怎么算出来的". Palette: warm cream paper background #F3EFE6, near-black ink #17150F, one accent red #D23A1E used sparingly; photoreal food is the only other colour. Premium and calm like Apple, Linear, Stripe or a good print magazine. Strictly NO McDonald'"'"'s logo, golden arches, brand packaging, wrappers or cups; NO neon, glow, dark cyberpunk, glassmorphism, heavy gradients; NO emoji; NO small coloured badge boxes; no extra slogans. Desktop web page, full page, portrait 2:3, opaque.'

page() { python3 "$G" --input "$BASE" --background opaque --size 1024x1536 --quality high --output "$1.png" --prompt "$KEEP Direction: $2" > "$1.log" 2>&1; echo "done $1"; }

BOARD='Using this page design as the exact visual reference (same style, colours, typography, food rendering), draw a 3-frame horizontal storyboard of its main animation, as three equal vertical panels side by side separated by thin gaps on a plain cream background. Each panel is a close crop of the ingredient section of the page at one moment. Show motion with ghosted previous positions, soft motion blur and thin dotted motion paths; no arrows with text. Do NOT write any frame numbers, captions or notes; only text that already exists in the page design may appear. No logos, no packaging, no neon, no glow, no emoji. Landscape 3:2, opaque.'

board() { python3 "$G" --input "$1.png" --background opaque --size 1536x1024 --quality high --output "$1-motion.png" --prompt "$BOARD Frames: $2" > "$1-motion.log" 2>&1; echo "done $1-motion"; }


KEEP2='Edit this real website screenshot: the "拆 · 只吃馅怎么算" page of a Chinese fitness meal-planning website. The burger ingredient module (the row of seven photoreal burger layer photos split into three outlined groups 吃掉 / 留到明早 / 下单去掉, with the calorie bar underneath) is already good: keep it essentially unchanged — same photos, same order, same grouping — and only restyle its labels, frames and spacing to match the new style. What must change is the OVERALL visual style and the TYPOGRAPHY and TEXT LAYOUT of the whole page: the page header (title, kicker, subtitle, burger mascot), section headings, the 吃法 selector, the 这一顿 summary, 省钱对比, and the overall grid, rhythm and decorative devices. Keep the top navigation bar as in the screenshot. Use these texts exactly as written and NO other text: "回到首页", "SPLIT SETS", "拆 · 只吃馅怎么算", "官方只公布整份营养。我们把它拆到每一种配料，于是「只吃馅」吃进去多少、面包留下多少，都能算出来。", "吃法", "整份吃", "下单去吉士", "到手只吃馅", "去吉士 + 只吃馅" (selected), "这一顿", "182", "大卡", "蛋白质 16 g · 碳水 2 g", the ingredient labels and calories as in the screenshot, "吃掉 182 大卡", "留到明早 157 大卡", "下单去掉 90 大卡", "省钱对比", "同一家店，同样 400 大卡以内、蛋白质 30 克以上", "只能整份吃", "¥32.0", "2 × 薄皮焦香V翅", "384 大卡 · 蛋白质 34 g · 碳水 12 g", "允许拆着吃", "¥27.8", "2 份人气经典随心配，高达吉士双牛堡去干酪、只吃馅", "365 大卡 · 蛋白质 33 g · 碳水 6 g，面包留作明天早餐", "怎么算出来的", plus the small design labels "01", "02", "03". Palette stays warm cream paper #F3EFE6, ink #17150F and accent red #D23A1E (red used sparingly); photoreal food is the only other colour. Strictly NO McDonald'"'"'s logo, golden arches, brand packaging or cups; NO neon, glow, cyberpunk, glassmorphism, heavy gradients; NO emoji; NO grid of small coloured badge boxes; NO plain thin-bordered white cards. Desktop web page, full page, portrait 2:3, opaque.'

style() { python3 "$G" --input "$BASE" --background opaque --size 1024x1536 --quality high --output "$1.png" --prompt "$KEEP2 Direction: $2" > "$1.log" 2>&1; echo "done $1"; }

TRAINBASE=base-train.png
KEEP3='Edit this real website screenshot: the "练 · 生成训练计划" page of a Chinese fitness meal-planning website (you set a calorie cap, a protein target and today'"'"'s muscle group; it shows the 3 cheapest McDonald'"'"'s order plans and a training-log style card for the chosen plan). Restyle it in the SAME "coach'"'"'s printed training sheet marked up by hand" style as its sister page: warm cream paper #F3EFE6 with a faint dot-grid paper texture in the header area, a very heavy bold black sans title, small red rubber-stamp section numbers 01 02 03 (red outlined square, slightly rotated, a bit uneven like real ink), near-black ink #17150F, and a red felt-tip pen layer (#D23A1E) of a few confident hand-drawn marks: loose circles, a scribbled underline under 生成训练计划 in the title, curved arrows and ticks. Keep ALL existing content and use these texts exactly, no other text: navigation as in the screenshot, "回到首页", "TRAIN", "练 · 生成训练计划", "下面的结果是 Skill 在一家门店快照上的真实输出，不需要 Token；装好以后，它按你的位置找最近的门店实时算。", "热量上限", "500", "大卡", "蛋白质", "30", "克", "今天练", "练腿" (selected), "练胸", "练背", "练手臂", "不限", "门店", "上海 · 人民广场", "麦当劳上海福州路餐厅 · 2026-10-16 晚餐时段快照", "选方案", "会员费从低到高", "方案 1", "¥28.9", "麦香鸡（下单去麦香鸡酱，只吃馅） + 麦麦脆汁鸡-琵琶腿", "452 大卡 · 蛋白质 30 g · 碳水 28 g", "方案 2", "¥29.9", "麦香鱼（下单去麦香鱼酱，只吃馅） + 麦麦脆汁鸡-琵琶腿", "方案 3", "¥30.0", "麦麦脆汁鸡-琵琶腿 + 吉士汉堡包（只吃馅）", "TODAY · LEG DAY", "今日训练：练腿", "Never skip leg day，鸡腿日更不能跳", "#", "动作", "每组", "组数", "吃法", "01", "麦香鸡", "1 个", "1 组", "下单去麦香鸡酱，只吃馅", "02", "麦麦脆汁鸡-琵琶腿", "动作要领", "只吃馅的，面包收进冰箱，明早当早餐", "训练量", "452", "会员费", "明早拉伸", "145", "怎么下单", "1 × 人气经典随心配：麦香鸡（下单去麦香鸡酱，到手只吃馅，面包留到下一顿） + 无糖可口可乐中杯", "1 × 麦麦脆汁鸡1块：麦麦脆汁鸡-琵琶腿", plus exactly two short handwritten red notes: "最便宜" next to plan 1 and "达标" next to the protein 30 g result. No McDonald'"'"'s logo, golden arches, packaging or cups; no neon, glow, cyberpunk, glassmorphism or heavy gradients; no emoji; no extra slogans. Desktop web page, full page, portrait 2:3, opaque.'
train() { python3 "$G" --input "$TRAINBASE" --background opaque --size 1024x1536 --quality high --output "$1.png" --prompt "$KEEP3 Layout direction: $2" > "$1.log" 2>&1; echo "done $1"; }

HOMEBASE=base-home-1440.png
KEEP4='Edit this real website screenshot: the one-screen landing page of a Chinese fitness meal-planning website. Keep exactly: the top navigation bar; the giant black headline in two lines "Go to Gym 不如" and "Go to ᗰ" where the last letter is a glossy gold 3D ᗰ; the three cute 3D food mascots in their exact poses (a fried chicken drumstick hanging from the letter t, a chicken nugget sitting on the m of Gym, a double cheeseburger hugging the gold ᗰ, all with red-white sweatbands and white sneakers); the three dashed-outline pill buttons "练 生成训练计划 →", "拆 只吃馅怎么算 →", "装 装到 WorkBuddy →" (each pill near its own mascot: 练 near the drumstick, 装 near the nugget, 拆 near the burger); and the subtitle "健身人群的麦当劳点餐 Skill" with the line "告诉它热量、蛋白质和今天练哪里，最便宜的点法和「只吃馅」的吃法帮你算好". ADD VISUAL GUIDANCE ELEMENTS — graphic devices that lead the eye from the headline to the three entry pills and give the page a clear reading path — as described in the direction below, and use the empty right and bottom areas. Palette: warm cream paper #F3EFE6, near-black ink #17150F, accent red #D23A1E, gold only on the ᗰ. Premium, witty, editorial; NO McDonald'"'"'s logo, golden arches or packaging; NO neon, glow, cyberpunk, glassmorphism; NO emoji; no extra slogans or text except what the direction explicitly allows. Landscape 3:2 desktop screen, opaque.'
home() { python3 "$G" --input "$HOMEBASE" --background opaque --size 1536x1024 --quality high --output "$1.png" --prompt "$KEEP4 Direction: $2" > "$1.log" 2>&1; echo "done $1"; }

case "${1:-pages}" in
pages)
page s1-stage "Product stage with an exploded view. The ingredient section becomes one large centred stage across the full width with lots of whitespace. A big photoreal double cheeseburger is exploded vertically along a central axis, its seven layers floating with even gaps (top bun, pickles with onion and ketchup, cheese, beef patty, cheese, beef patty, bottom bun); thin black leader lines run from each layer to its label and calories, alternating left and right. The selected way is acted out on the stage: the two beef patties stay sharp and lit on the centre axis (吃掉 182 大卡); the two buns and the pickles slide out to the left and become soft semi-transparent ghosts (留到明早 157 大卡); the two cheese slices slide out to the right, greyed and outlined only (下单去掉 90 大卡). Faint horizontal motion streaks behind the sliding layers show movement. The four 吃法 options become one centred segmented control above the stage. The number 182 is set huge in red beside the stage with 这一顿 and 大卡. Below, 省钱对比 as two calm price columns with a thin vertical divider and ¥27.8 in red. Apple product page feel." &
page s2-barbell "Gym barbell loading, sporty and energetic. The ingredient section is a horizontal barbell spanning the page width; each ingredient is a weight plate on the bar, made of photoreal food (beef patties, cheese slices, buns, pickles), plate diameter roughly proportional to its calories. The eaten items (two beef patties) stay loaded on the bar in the middle; the buns and pickles have been moved onto a simple weight rack on the left labelled 留到明早 157 大卡; the two cheese slices lie on the floor line on the right, greyed and crossed with one thin red line, labelled 下单去掉 90 大卡. A large mechanical split-flap scoreboard at the top right shows 182 (cream flaps, black digits) with 这一顿 above and 大卡 beside. Heavy condensed sports numerals, generous whitespace, two or three thin red diagonal speed lines near the moving plates as the only motion cue. 省钱对比 styled like a match scoreboard: 只能整份吃 ¥32.0 versus 允许拆着吃 ¥27.8, the winner ¥27.8 in red. The 吃法 options as a row of bold pill buttons like gym plate selectors. Training-log editorial vibe on cream paper." &
page s3-poster "Editorial magazine spread with giant typography. The visual anchor is a full-width number line set extremely large in a heavy condensed typeface: 429 crossed out in grey, a thin arrow, then 182 in red, with 大卡 small beside it (the only allowed new text is 429). Photoreal cut-out burger layers are tucked between and around the giant digits with real depth: some layers in front of the numbers, some behind them, casting soft shadows on the paper. Asymmetric 12-column grid with wide margins and one thin red hairline. The seven ingredients also appear as a neat flat-lay row of cut-outs with small captions; the removed cheese slices are drawn as thin outlines only. The 吃法 options are plain text tabs with an underline under the selected one. 省钱对比 as one big typographic line: ¥32.0 struck through in grey and ¥27.8 in red, with the two descriptions as small captions under each. Feels like Monocle or Kinfolk meets a Swiss poster." &
page s4-flatlay "Warm top-down flat-lay sorting board. A large light linen-textured surface spans the page width, photographed from directly above in soft natural daylight with gentle shadows. It is divided into three zones by thin pencil lines: on the left a plain white plate holding the two beef patties, labelled 吃掉 182 大卡; in the middle a lidded glass meal-prep container holding the two buns and the pickles, labelled 留到明早 157 大卡; on the right the two cheese slices lying apart with one thin red strike line, labelled 下单去掉 90 大卡. Each item has a small neat handwritten-style calorie caption. Thin dotted arcs show where each item travelled from a small intact burger at the top-left corner. The 吃法 options are a pill segmented control above the board, and 这一顿 182 大卡 sits as a very large number at the top right of the board. 省钱对比 below as two calm columns, ¥27.8 in red. Calm, appetising, lifestyle magazine feel." &
wait ;;
boards)
board s1-stage "(1) the burger whole and intact on the centre axis, 整份吃 selected, number shows 429; (2) the burger mid-explosion, layers drifting apart vertically with motion blur, 去吉士 + 只吃馅 being selected; (3) final state: patties on the axis, buns and pickles ghosted to the left, cheese outlined to the right, number shows 182 in red." &
board s2-barbell "(1) all seven food plates loaded on the bar, scoreboard flaps show 429; (2) plates sliding off the bar ends with speed lines, scoreboard flaps mid-flip; (3) only the two patties remain on the bar, buns and pickles on the rack, cheese on the floor, scoreboard shows 182." &
board s3-poster "(1) giant 429 alone with the burger layers stacked neatly in front of it; (2) 429 being struck through while the layers peel apart and drift, the red 182 sliding in from the right; (3) final: 429 crossed out, 182 in red, layers settled between the digits." &
board s4-flatlay "(1) the intact burger in the top-left corner of the linen board, zones empty; (2) the layers lifting apart and gliding along dotted arcs toward the plate, the container and the strike zone, with soft motion blur; (3) final: patties on the plate, buns and pickles in the container, cheese struck through, 182 shown large." &
wait ;;
style)
style t1-editorial "Editorial magazine typography, like a well-designed Chinese culture magazine (Monocle meets 单读). The page title 拆 · 只吃馅怎么算 is set very large in a heavy Chinese serif (Song/Ming style, like Source Han Serif Heavy), tight and elegant; SPLIT SETS in letter-spaced small caps above it; the subtitle becomes a refined lead paragraph in a lighter serif with generous leading, in a narrow measure. A clear editorial grid: a slim left margin column carries small section numbers 01, 02, 03 aligned with each section, the content sits in the wider right columns. Section heads (吃法, 这一顿, 省钱对比) are serif with a short ink rule; small labels stay in a clean sans; big numbers stay in a condensed sans. The burger mascot sits in the margin beside the title like a magazine illustration. 省钱对比 is laid out like a magazine comparison spread with the two prices as large display figures and the details as captions. Restrained, literary, lots of air." &
style t2-sport "Sports poster / training manual, bold and kinetic. The page title is set in a huge, very heavy condensed sans with tight leading, 拆 enormous on its own line and 只吃馅怎么算 next to or below it; SPLIT SETS runs vertically (rotated 90 degrees) along the left margin; heavy 6px black rules and one thick red stripe as section dividers; section numbers 01 02 03 as large outlined numerals; the 吃法 selector as chunky square-cornered buttons. 省钱对比 sits on one full-width near-black ink band with cream text and ¥27.8 in red, the only dark area on the page. Asymmetric and energetic like Nike Training Club or gym signage, but clean." &
style t3-swiss "Swiss International Typographic Style. A strict 12-column grid with very faint visible column guide lines; extreme scale contrast between huge and tiny type; everything flush-left ragged-right; a single small solid red square as the accent mark; section labels are tiny index numbers 01 02 03 with hairlines; the title placed asymmetrically starting at column 4 while the burger mascot sits in columns 1 to 3; 182 set enormous and aligned to the grid; 省钱对比 as a precise two-column data table with big tabular numerals and hairline rows. Precise, airy, rational, like Müller-Brockmann or Vignelli." &
style t4-coach "A coach's printed training sheet marked up by hand. The page itself keeps clean printed typography with a strong, bold black sans title and a faint dot-grid paper texture in the header area like a training log sheet; then a coach has annotated it with a red felt-tip pen: a loose hand-drawn circle around 182, a quick scribbled underline under 只吃馅 in the title, a curved hand-drawn arrow from 去吉士 + 只吃馅 down to the ingredient groups, a hand-drawn tick next to ¥27.8, and exactly two short handwritten red notes: \"就吃这个\" next to the 吃掉 group and \"省 ¥4.2\" next to ¥27.8. Section numbers 01 02 03 stamped in a small rubber-stamp style. Playful but tidy, the annotations few and confident." &
wait ;;
style3)
style t3-swiss "Radical Swiss International Typographic Style — it must look clearly different from the screenshot. Thin vertical column lines of a 12-column grid are visibly drawn across the WHOLE page in a light rule colour, and every element snaps to them. Extreme scale contrast: the title 拆 · 只吃馅怎么算 is set enormous, broken over three lines, flush left from column 5, heavy grotesk, tight leading; the burger mascot sits small in columns 1 to 3; tiny index numbers 01 02 03 with long hairlines mark each section in column 1. The 这一顿 figure 182 is set gigantic (about a quarter of the page width) and bleeds close to the right edge, with 大卡 tiny beside it. One solid red square (about 40px) as the only ornament, repeated once per section. 省钱对比 as a precise table spanning columns 5 to 12 with huge tabular numerals and hairline rows. Lots of empty grid space; rational, rigorous, poster-like." &
wait ;;
train)
train r1-markup "Keep the current page structure and layout exactly (header, a parameter strip with four fields, three plan columns, then the training log table and score row), only apply the coach style: heavy title with the red underline, stamps 01 on the parameter strip, 02 on 选方案, 03 on the training log; the red pen circles ¥28.9 of plan 1 with the note 最便宜, draws a curved arrow from the selected 练腿 chip down toward the training log, ticks the 蛋白质 30 g score with the note 达标, and puts a quick red underline under 只吃馅的，面包收进冰箱，明早当早餐. Section titles become big bold headings." &
train r2-clipboard "The training log becomes a physical printed workout sheet clipped to a dark wooden clipboard with a metal clip at the top, lying slightly rotated on the cream page with a soft shadow; the table, the score row and 怎么下单 are printed on the sheet, and the red pen marks (circle, tick with 达标, underline) are on the sheet itself. Above it, the parameter strip and the three plans stay as clean printed rows with stamps 01 and 02 and the circled ¥28.9 with 最便宜; stamp 03 sits on the sheet. Heavy title with the red underline." &
train r3-columns "Two-column layout under the header: a narrow left column (about one third) is the coach's checklist — stamp 01 with the four parameters stacked vertically (热量上限 500 大卡, 蛋白质 30 克, 今天练 chips, 门店), then stamp 02 with the three plans stacked as a vertical list, plan 1 circled in red with 最便宜 and a red arrow pointing right; the wide right column (two thirds) holds the training log card with stamp 03, TODAY · LEG DAY as a very large heading, the table, score row with the ticked 蛋白质 30 g and 达标, and 怎么下单. Heavy title with the red underline across the top." &
wait ;;
home)
home h1-redpen "Coach's red pen route, matching the inner pages: a faint dot-grid paper texture over the background; a red felt-tip pen strikes through the word Gym in the headline with one confident line and draws a loose circle around the gold ᗰ, with a short handwritten red note 就去这家 beside the circle; small red rubber-stamp numbers 01, 02, 03 (red outlined squares, slightly rotated) sit on the pills 练, 拆, 装; a hand-drawn red dashed route line with arrowheads connects the pills in order 练 → 拆 → 装 like a training circuit, sweeping through the empty space. Only new text allowed: 就去这家, 01, 02, 03." &
home h2-track "Running-track guidance: a single elegant athletics lane (two thin parallel ink lines with faint lane texture between them) sweeps across the page in a big S curve from the top-left behind the headline to the bottom-right, passing right next to each mascot like stations on a route; at each station a small round marker with a number 01, 02, 03 sits on the lane next to the matching pill (练 01, 拆 02, 装 03); a thin finish line with a checkered stripe at the lane end bottom-right. Movement feels like the eye runs along the track. Only new text allowed: 01, 02, 03." &
home h3-focus "Focal composition: one large solid red circle (like a rising sun or a gym weight plate) sits behind the gold ᗰ and the burger, making it the clear focal point; a wide soft diagonal band of very light tint leads from the top-left headline down to the ᗰ; a thin oversized arrow sweeps from the word Gym across to the ᗰ; at the bottom edge a slim horizontal ticker strip in ink with cream text scrolls real numbers separated by dots: ¥27.8 · 182 大卡 · 只吃馅 · 去吉士 · 9/9 核价一致 . Only new text allowed is that ticker." &
home h4-steps "Sneaker-footprint guidance: small neat white-and-ink sneaker footprints walk from each mascot to its own pill (from the drumstick down to 练, from the nugget across to 装, from the burger right to 拆), as if the mascots just walked over to show the way; a faint chalk-like floor line under the headline like a gym floor marking, with subtle lane tick marks; the footprints get slightly larger near the pills to pull the eye there. No new text." &
wait ;;
esac
